async function openClubInvite(kind,id){const request=kind==='meal'?clubRequest:studyClubRequest,data=await request(),club=data.clubs.find(c=>c.id===id);if(!club)return;const users=data.users.filter(u=>!club.members.some(m=>m.id===u.id));const d=extraDialog('정기 모임 회원 초대',`<p>${esc(club.name)} · ${esc(club.restaurant)}</p><form id="recurring-invite-form" class="board-form" data-kind="${kind}" data-id="${id}"><p class="muted">초대받은 회원이 알림에서 참여 요일을 선택해 수락하면 모임에 참여합니다.</p><div class="meal-member-list">${users.map(u=>`<label class="meal-member"><input type="checkbox" name="recipients" value="${u.id}">${esc(u.name)}</label>`).join('')||'<p>초대할 회원이 없습니다.</p>'}</div><button class="primary" ${users.length?'':'disabled'}>선택한 회원 초대</button><p role="status" class="board-status"></p></form>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-meal-club-invite],[data-study-club-invite]');if(!b)return;const meal=b.hasAttribute('data-meal-club-invite');openClubInvite(meal?'meal':'study',Number(b.getAttribute(meal?'data-meal-club-invite':'data-study-club-invite'))).catch(error=>alert(error.message));});
document.addEventListener('submit',async e=>{const f=e.target;if(f.id!=='recurring-invite-form')return;e.preventDefault();const b=f.querySelector('button'),recipients=new FormData(f).getAll('recipients').map(Number);b.disabled=true;try{await(f.dataset.kind==='meal'?clubRequest:studyClubRequest)('/invite',{id:Number(f.dataset.id),recipients});f.querySelector('[role=status]').textContent='초대를 보냈습니다. 초대받은 회원의 알림에 표시됩니다.';}catch(error){f.querySelector('[role=status]').textContent=error.message;}finally{b.disabled=false;}});

